import csv
import io
import re


def parse_csv(raw_csv: str):
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False)
    parsed = list(reader)

    def clean(value):
        value = str(value)
        if len(value) >= 2 and value[0] == "'" and value[-1] == "'":
            value = value[1:-1].replace("''", "'")
        return value

    records = [[clean(value) for value in row] for row in parsed]

    def is_number(value):
        return bool(re.fullmatch(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)", value.strip()))

    header_index = None
    for index, row in enumerate(records):
        if not row or len(row) != 8 or not any(value.strip() for value in row):
            continue
        if is_number(row[0]):
            continue
        if any(is_number(value) for value in row[1:]):
            continue
        if any(is_number(next_row[0]) for next_row in records[index + 1:] if next_row):
            header_index = index
            break

    if header_index is not None:
        columns = records[header_index][:]
        data = records[header_index + 1:]
    else:
        columns = []
        data = records

    width = max([8, len(columns)] + [len(row) for row in data])
    if columns:
        columns += [f"column_{i}" for i in range(len(columns) + 1, width + 1)]
    else:
        columns = [f"column_{i}" for i in range(1, width + 1)]

    rows = [row + [""] * (width - len(row)) for row in data]
    return {"columns": columns, "rows": rows}
